sys_script_include.script:
var TaskUtils = Class.create();
TaskUtils.prototype = {
    initialize: function() {
        this._taskTable = 'x_1610434_event_0_event_task';
    },

    getTasksForEvent: function(_eventId) {
        var _taskList = [];
        var _taskGR = new GlideRecordSecure(this._taskTable);
        _taskGR.addQuery('event_id', _eventId);
        _taskGR.query();
        while (_taskGR.next()) {
            _taskList.push(this._mapTaskFields(_taskGR));
        }
        return _taskList;
    },

    isTaskOverdue: function(_taskId) {
        var _taskGR = new GlideRecordSecure(this._taskTable);
        _taskGR.addQuery('sys_id', _taskId);
        _taskGR.query();
        if (_taskGR.next()) {
            var _dueDate = new GlideDateTime(_taskGR.getValue('due_date'));
            return _dueDate < new GlideDateTime();
        }
        return false;
    },

    getTaskDetailsById: function(_taskId) {
        var _taskGR = new GlideRecordSecure(this._taskTable);
        _taskGR.addQuery('sys_id', _taskId);
        _taskGR.query();
        if (_taskGR.next()) {
            return this._mapTaskFields(_taskGR);
        }
        return null;
    },

    getTasksByDueDate: function(_dueDate) {
        var _taskList = [];
        var _taskGR = new GlideRecordSecure(this._taskTable);

        var _startOfDay = new GlideDateTime(_dueDate + " 00:00:00");
        var _endOfDay = new GlideDateTime(_dueDate + " 23:59:59");

        _taskGR.addQuery('due_date', '>=', _startOfDay);
        _taskGR.addQuery('due_date', '<=', _endOfDay);
        _taskGR.query();

        while (_taskGR.next()) {
            _taskList.push(this._mapTaskFields(_taskGR));
        }
        return _taskList;
    },

    _mapTaskFields: function(_taskGR) {
        return {
            sysId: _taskGR.getUniqueValue(),
            eventId: _taskGR.getValue('event_id'),
            taskName: _taskGR.getValue('task_name'),
            assignedTo: _taskGR.getValue('assigned_to'),
            dueDate: _taskGR.getValue('due_date'),
            status: _taskGR.getValue('status'),
            priority: _taskGR.getValue('priority')
        };
    },

    type: 'TaskUtils'
};
